namespace MiniPdf {
    internal static partial class SelfTest {
        delegate bool MergeChild(IntPtr window,IntPtr parameter);
        [DllImport("user32.dll")]static extern bool EnumChildWindows(IntPtr window,MergeChild callback,IntPtr parameter);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr window,StringBuilder text,int count);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr window,StringBuilder text,int count);
        [DllImport("user32.dll",CharSet=CharSet.Unicode,EntryPoint="SendMessageW")]static extern IntPtr MergeText(IntPtr window,uint message,IntPtr wParam,string text);
        static object MergeValue(object value,string name){return value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(value);}
        static List<object> MergeCards(MergeWindow.MergeBoard board){return ((IEnumerable)MergeValue(board,"cards")).Cast<object>().ToList();}
        static Rectangle MergeRect(MergeWindow.MergeBoard board,MergeGroup group,int page){return (Rectangle)MergeValue(MergeCards(board).First(c=>(MergeGroup)MergeValue(c,"Group")==group&&(page<0?(bool)MergeValue(c,"Header"):(MergePage)MergeValue(c,"Page")==group.Pages[page])),"Bounds");}
        static Point MergePoint(MergeWindow.MergeBoard board,Rectangle bounds,double fraction=.5,int height=85){return new Point(bounds.Left+(int)(bounds.Width*fraction)+board.AutoScrollPosition.X,bounds.Top+height+board.AutoScrollPosition.Y);}
        static void MergeMouse(MergeWindow.MergeBoard board,int message,Point point){N.SendMessage(board.Handle,(uint)message,message==0x202?IntPtr.Zero:new IntPtr(1),Position(point));if(message==0x202)Application.DoEvents();}
        static void MergeDrag(MergeWindow.MergeBoard board,Point from,Point to,bool release=true){MergeMouse(board,0x201,from);MergeMouse(board,0x200,to);if(release)MergeMouse(board,0x202,to);}
        static void MergeTick(MergeWindow.MergeBoard board,int count,bool elapsed=false){var timer=(System.Windows.Forms.Timer)MergeValue(board,"scroll");if(!timer.Enabled)throw new Exception("Merge drag timer did not start");if(elapsed)board.GetType().GetField("hoverAt",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(board,unchecked(Environment.TickCount-800));var tick=typeof(System.Windows.Forms.Timer).GetMethod("OnTick",BindingFlags.Instance|BindingFlags.NonPublic);for(int i=0;i<count;i++)tick.Invoke(timer,new object[]{EventArgs.Empty});}
        static void MergeKey(Control control,Keys key){control.GetType().GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(control,new object[]{new Message(),key});Application.DoEvents();}
        static string MergeSequence(MergePlan plan){return String.Join(",",plan.AllPages().Select(p=>p.Name.Substring(0,1)+(p.Index+1)));}
        static int MergeHistory(MergePlan plan){return ((ICollection)MergeValue(plan,"undo")).Count;}
        static MergePlan ScanPlan(string directory,bool uneven=false){var plan=new MergePlan();plan.Add(PdfDocument.Open(Path.Combine(directory,uneven?"scan-odd-short.pdf":"scan-odd.pdf"),""),"A-odd.pdf");plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-even.pdf"),""),"B-even.pdf");return plan;}
        static void MergeInputs(string directory){using(var source=PdfDocument.Open(Path.Combine(directory,"features.pdf"),"")){source.Extract(new[]{0,2,4,6},Path.Combine(directory,"scan-odd.pdf"));source.Extract(new[]{1,3,5,7},Path.Combine(directory,"scan-even.pdf"));source.Extract(new[]{0,2,4},Path.Combine(directory,"scan-odd-short.pdf"));}}
        static string MergeHash(string path){using(var sha=SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(path)));}
        static void SaveMerge(MergePlan plan,string directory,string name){using(var doc=plan.Build()){doc.Save(Path.Combine(directory,name));Assert(doc.Count==plan.Count,"saved "+name+" retains all arranged pages");}}
        static void MergeOrdering(string directory){var hashes=new[]{"scan-odd.pdf","scan-even.pdf","scan-odd-short.pdf"}.ToDictionary(n=>n,n=>MergeHash(Path.Combine(directory,n)));
            string[] orders={"A1,B1,A2,B2,A3,B3,A4,B4","B1,A1,B2,A2,B3,A3,B4,A4","A1,B4,A2,B3,A3,B2,A4,B1","A1,A2,B1,B2,A3,A4,B3,B4"};string[] outputs={"interleave-a-first.pdf","interleave-b-first.pdf","interleave-second-reversed.pdf","interleave-blocks.pdf"};
            for(int mode=1;mode<=4;mode++)using(var plan=ScanPlan(directory)){plan.Groups[0].Expanded=true;var a=plan.Groups[0].Pages[1];int history=MergeHistory(plan);plan.Arrange(mode,2);Assert(plan.Groups.Count==1&&plan.Groups[0].Expanded&&MergeSequence(plan)==orders[mode-1],"arrangement mode "+mode+" produces the expected complete page order");Assert(plan.AllPages().Contains(a)&&a.Name=="A-odd.pdf"&&a.Index==1,"arrangement retains original source identities and page numbers");Assert(MergeHistory(plan)==history+1,"arrangement consumes one undo step");SaveMerge(plan,directory,outputs[mode-1]);plan.Undo();Assert(plan.Groups.Count==2&&plan.Groups[0].Expanded&&!plan.Groups[1].Expanded&&MergeSequence(plan)=="A1,A2,A3,A4,B1,B2,B3,B4","undo restores both file containers and expansion states");plan.Redo();Assert(MergeSequence(plan)==orders[mode-1],"redo restores arrangement mode "+mode);}
            using(var plan=ScanPlan(directory,true)){plan.Arrange(1);Assert(MergeSequence(plan)=="A1,B1,A2,B2,A3,B3,B4","uneven scans append all remaining pages without losing or duplicating them");SaveMerge(plan,directory,"interleave-uneven.pdf");}
            using(var plan=ScanPlan(directory)){using(var source=PdfDocument.Open(Path.Combine(directory,"features.pdf"),""))source.Extract(new[]{0},Path.Combine(directory,"scan-third.pdf"));plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-third.pdf"),""),"C-extra.pdf");plan.Groups.Insert(1,new MergeGroup{Name="Empty"});var extra=plan.Groups[3];plan.Arrange(1);Assert(plan.Groups.Count==3&&plan.Groups[1].Name=="Empty"&&plan.Groups[2]==extra&&MergeSequence(plan)==orders[0]+",C1","interleaving skips empty groups and preserves later files and their relative order");SaveMerge(plan,directory,"interleave-extra.pdf");}
            using(var plan=ScanPlan(directory)){plan.Groups[0].Pages[1].Rotation=1;plan.Arrange(1);Assert(plan.AllPages()[2].Rotation==1,"interleaving preserves per-page rotations");SaveMerge(plan,directory,"interleave-rotated.pdf");plan.Arrange(0);Assert(plan.Groups.Count==2&&plan.Groups.TrueForAll(g=>g.Expanded)&&MergeSequence(plan)=="A1,A2,A3,A4,B1,B2,B3,B4","regrouping reconstructs source files in original page order");SaveMerge(plan,directory,"interleave-regrouped.pdf");plan.Undo();Assert(plan.Groups.Count==1&&MergeSequence(plan)==orders[0],"regrouping is reversible in one step");}
            using(var plan=ScanPlan(directory)){plan.Groups[0].Pages.Insert(1,new MergePage{Source=plan.Groups[0].Pages[0].Source,Name="A-odd.pdf",Index=0,Rotation=2});plan.Arrange(1);plan.Arrange(0);Assert(plan.Groups[0].Pages[0].Rotation==0&&plan.Groups[0].Pages[1].Rotation==2,"regrouping keeps duplicate source pages in stable order");int count=MergeHistory(plan);bool invalid=false;try{plan.Arrange(4,0);}catch(InvalidOperationException){invalid=true;}Assert(invalid&&count==MergeHistory(plan),"invalid block sizes are rejected without changing history");plan.Arrange(1);count=MergeHistory(plan);invalid=false;try{plan.Arrange(1);}catch(InvalidOperationException){invalid=true;}Assert(invalid&&count==MergeHistory(plan),"a single file cannot silently interleave with itself");plan.Undo();plan.Arrange(4,10000);Assert(MergeSequence(plan)=="A1,A1,A2,A3,A4,B1,B2,B3,B4","oversized blocks append each input once");}
            Assert(hashes.All(p=>MergeHash(Path.Combine(directory,p.Key))==p.Value),"all source scan files remain byte-identical after arranging, saving and undoing");
        }
        static void MergeLine(MergeWindow.MergeBoard board,int expectedX,string label){var drop=MergeValue(board,"drop");Assert(drop!=null,label+" exposes an insertion destination");var line=(Rectangle)MergeValue(drop,"Line");Assert(line.Left==expectedX,label+" marks the actual thumbnail edge");using(var bitmap=new Bitmap(board.Width,board.Height)){board.DrawToBitmap(bitmap,board.ClientRectangle);int x=line.Left+board.AutoScrollPosition.X,y=line.Top+50+board.AutoScrollPosition.Y;Assert(x>=0&&y>=0&&x<bitmap.Width&&y<bitmap.Height&&bitmap.GetPixel(x,y).ToArgb()==Color.FromArgb(28,132,217).ToArgb(),label+" paints a visible blue insertion line");}}
        static void MergeBoardDetails(string directory){UiText.English=true;using(var dialog=new MergeWindow(null)){dialog.ClientSize=new Size(1050,700);dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""),"A-odd.pdf");dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-even.pdf"),""),"B-even.pdf");dialog.Show();Application.DoEvents();var board=dialog.Controls.OfType<MergeWindow.MergeBoard>().Single();board.Rebuild();var a=dialog.Plan.Groups[0];var b=dialog.Plan.Groups[1];Assert(MergeCards(board).Count==2,"collapsed files each occupy one stack thumbnail");var r=MergeRect(board,a,-1);var plus=MergePoint(board,r,.09,15);MergeDrag(board,plus,plus);Assert(a.Expanded&&MergeCards(board).Count==a.Pages.Count+1,"plus expands the file directly into its pages without an extra cover card");Assert(MergeCards(board).Count(c=>(MergePage)MergeValue(c,"Page")==a.Pages[0])==1,"expanded first page appears exactly once");MergeDrag(board,plus,plus);Assert(!a.Expanded&&MergeCards(board).Count==2,"minus collapses the file back into a stack thumbnail");
                a.Expanded=b.Expanded=true;board.Rebuild();Assert(MergeCards(board).Count==8&&MergeCards(board).Count(c=>(MergePage)MergeValue(c,"Page")==null)==0,"fully expanded files contain only real pages");Assert(MergeRect(board,a,1).Left-MergeRect(board,a,0).Right>=20,"page thumbnails have wider clear gaps for insertion markers");Assert(MergeRect(board,b,0).Left-MergeRect(board,a,3).Right>=44,"file boundaries have extra spacing around the permanent divider");var dividers=(List<Rectangle>)MergeValue(board,"dividers");Assert(dividers.Count>=2,"permanent dividers distinguish adjacent files and the final boundary");using(var bitmap=new Bitmap(board.Width,board.Height)){board.DrawToBitmap(bitmap,board.ClientRectangle);var divider=dividers[0];Assert(bitmap.GetPixel(divider.Left,divider.Top+60).ToArgb()==Color.FromArgb(130,146,164).ToArgb(),"file boundary is visible in the rendered native board");}
                var moving=a.Pages[0];r=MergeRect(board,a,2);var from=MergePoint(board,MergeRect(board,a,0));var to=MergePoint(board,r,.2);MergeDrag(board,from,to,false);MergeLine(board,r.Left-10,"drop before page 3");Assert(board.AccessibleDescription.Contains("A-odd.pdf")&&board.AccessibleDescription.Contains("Original page 3"),"drag hint names the destination file and original page");CaptureDialog(dialog,Path.Combine(directory,"combine-insertion-before.png"));MergeMouse(board,0x202,to);Assert(a.Pages[1]==moving&&MergeSequence(dialog.Plan)=="A2,A1,A3,A4,B1,B2,B3,B4","left-half drop inserts before the exact target page");Assert(board.Selection().Count==1&&board.Selection()[0]==moving,"moved page remains selected after layout is rebuilt");Assert(!board.Capture&&board.AccessibleDescription=="","completed drop releases capture and removes its insertion hint");
                int history=MergeHistory(dialog.Plan);r=MergeRect(board,a,1);MergeDrag(board,MergePoint(board,r),MergePoint(board,r,.9));Assert(history==MergeHistory(dialog.Plan),"dropping a page immediately after itself does not create undo history");dialog.Plan.Undo();board.ResetSelection();a=dialog.Plan.Groups[0];b=dialog.Plan.Groups[1];moving=a.Pages[0];r=MergeRect(board,a,1);to=MergePoint(board,r,.8);MergeDrag(board,MergePoint(board,MergeRect(board,a,0)),to,false);MergeLine(board,r.Right+10,"drop after page 2");MergeMouse(board,0x202,to);Assert(a.Pages[1]==moving,"right-half drop inserts after the target page");dialog.Plan.Undo();board.ResetSelection();a=dialog.Plan.Groups[0];b=dialog.Plan.Groups[1];moving=a.Pages[0];r=MergeRect(board,b,0);to=MergePoint(board,r,.15);MergeDrag(board,MergePoint(board,MergeRect(board,a,0)),to,false);MergeLine(board,r.Left-10,"cross-file drop");MergeMouse(board,0x202,to);Assert(a.Pages.Count==3&&b.Pages[0]==moving&&moving.Name=="A-odd.pdf","dragging across the divider preserves the page's original source");Assert(board.Selection().Count==1&&board.Selection()[0]==moving,"selection follows a page moved into another file group");dialog.Plan.Undo();board.ResetSelection();Assert(dialog.Plan.Groups[0].Pages.Count==4&&dialog.Plan.Groups[1].Pages.Count==4,"cross-file move is undone as one operation");dialog.Plan.Redo();board.ResetSelection();Assert(dialog.Plan.Groups[1].Pages[0].Name=="A-odd.pdf","cross-file move can be redone without changing provenance");dialog.Plan.Undo();board.ResetSelection();
                a=dialog.Plan.Groups[0];b=dialog.Plan.Groups[1];r=MergeRect(board,b,b.Pages.Count-1);to=MergePoint(board,r,.9);MergeDrag(board,MergePoint(board,MergeRect(board,a,0),.5,15),to,false);MergeLine(board,r.Right+10,"whole-file drop");MergeMouse(board,0x202,to);Assert(dialog.Plan.Groups[1]==a&&a.Pages.Count==4,"dragging the expanded file title moves the entire file, not its first page");dialog.Plan.Undo();board.ResetSelection();a=dialog.Plan.Groups[0];b=dialog.Plan.Groups[1];r=MergeRect(board,b,0);to=MergePoint(board,r,0);to.X-=3;moving=a.Pages[0];MergeDrag(board,MergePoint(board,MergeRect(board,a,0)),to);Assert(b.Pages[0]==moving,"drop in the gap before a file inserts at its leading boundary");dialog.Plan.Undo();board.ResetSelection();
                string original=MergeSequence(dialog.Plan);history=MergeHistory(dialog.Plan);a=dialog.Plan.Groups[0];b=dialog.Plan.Groups[1];from=MergePoint(board,MergeRect(board,a,0));to=MergePoint(board,MergeRect(board,b,0));MergeDrag(board,from,to,false);MergeKey(board,Keys.Escape);MergeMouse(board,0x202,to);Assert(MergeSequence(dialog.Plan)==original&&MergeHistory(dialog.Plan)==history&&!board.Capture,"Esc cancels the drag without altering pages or undo history");MergeDrag(board,from,to,false);MergeMouse(board,0x202,new Point(-15,-15));Assert(MergeSequence(dialog.Plan)==original&&board.AccessibleDescription=="","release outside the viewport cancels instead of appending unexpectedly");MergeDrag(board,from,to,false);board.Capture=false;MergeMouse(board,0x202,to);Assert(MergeSequence(dialog.Plan)==original&&!board.Capture,"losing mouse capture cancels the pending drop safely");
                b.Expanded=false;board.Rebuild();moving=a.Pages[0];to=MergePoint(board,MergeRect(board,b,-1),.2);MergeDrag(board,MergePoint(board,MergeRect(board,a,0)),to,false);Assert(board.AccessibleDescription.Contains("hover to expand"),"collapsed destination advertises hover expansion in English");MergeTick(board,1);Assert(!b.Expanded,"brief hover does not expand a destination prematurely");MergeTick(board,1,true);Assert(b.Expanded&&board.Capture&&MergeCards(board).Count==8,"hover expands a collapsed destination while retaining mouse capture");MergeMouse(board,0x202,to);Assert(b.Pages[0]==moving,"expanded hover drop recomputes and uses the actual destination");dialog.Plan.Undo();board.ResetSelection();
                a=dialog.Plan.Groups[0];b=dialog.Plan.Groups[1];a.Expanded=b.Expanded=true;board.Rebuild();dialog.ClientSize=new Size(700,460);Application.DoEvents();board.AutoScrollPosition=Point.Empty;r=MergeRect(board,a,0);moving=a.Pages[0];to=new Point(180,board.ClientSize.Height-5);MergeDrag(board,MergePoint(board,r),to,false);MergeTick(board,6);Assert(board.AutoScrollPosition.Y<0&&board.Capture&&board.AccessibleDescription.Length>0,"edge dragging scrolls the board and refreshes the destination without losing capture");MergeMouse(board,0x202,to);Assert(dialog.Plan.AllPages().IndexOf(moving)>0&&!board.Capture,"dropping after auto-scroll places the page later in the visible sequence");dialog.Plan.Undo();board.ResetSelection();dialog.ClientSize=new Size(1050,700);board.AutoScrollPosition=Point.Empty;board.Rebuild();Application.DoEvents();
                a=dialog.Plan.Groups[0];b=dialog.Plan.Groups[1];moving=a.Pages[0];MergeDrag(board,MergePoint(board,MergeRect(board,a,0)),MergePoint(board,MergeRect(board,b,0)),false);dialog.ClientSize=new Size(900,650);dialog.Controls.OfType<FlowLayoutPanel>().SelectMany(p=>p.Controls.OfType<TrackBar>()).Single().Value=180;Application.DoEvents();Assert(board.Capture&&board.AccessibleDescription.Length>0,"resizing the window and thumbnails preserves the active drag");to=MergePoint(board,MergeRect(board,a,2),.15);MergeMouse(board,0x202,to);Assert(a.Pages[1]==moving,"release after resize recomputes the destination from the current layout");dialog.Plan.Undo();board.ResetSelection();dialog.Controls.OfType<FlowLayoutPanel>().SelectMany(p=>p.Controls.OfType<TrackBar>()).Single().Value=120;dialog.ClientSize=new Size(1050,700);board.AutoScrollPosition=Point.Empty;board.Rebuild();CaptureDialog(dialog,Path.Combine(directory,"combine-expanded-detail.png"));
                a=dialog.Plan.Groups[0];r=MergeRect(board,a,1);MergeMouse(board,0x200,MergePoint(board,r));var tips=(ToolTip)MergeValue(board,"tips");Assert(tips.GetToolTip(board).Contains("A-odd.pdf")&&tips.GetToolTip(board).Contains("Original page 2"),"page tooltip retains the full source filename and original page number");dialog.DialogResult=DialogResult.OK;dialog.Close();}
        }
        static void MergeShortcuts(string directory){UiText.English=true;using(var dialog=new MergeWindow(null)){dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""),"A-odd.pdf");dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-even.pdf"),""),"B-even.pdf");dialog.Show();Application.DoEvents();var board=dialog.Controls.OfType<MergeWindow.MergeBoard>().Single();board.Focus();for(int key=2;key<=4;key++){MergeKey(dialog,Keys.Control|(Keys)((int)Keys.D0+key));Assert(dialog.Plan.Groups.Count==1,"Ctrl+"+key+" invokes a native arrangement command");MergeKey(dialog,Keys.Control|Keys.D1);Assert(dialog.Plan.Groups.Count==2&&MergeSequence(dialog.Plan)=="A1,A2,A3,A4,B1,B2,B3,B4","Ctrl+1 restores source ordering after Ctrl+"+key);}
                bool answered=false;using(var timer=new System.Windows.Forms.Timer{Interval=80}){timer.Tick+=delegate{foreach(Form open in Application.OpenForms)if(open.Text==UiText.Get("每 N 页交错")){timer.Stop();open.Controls.OfType<TextBox>().Single().Text="2";((Button)open.AcceptButton).PerformClick();answered=true;break;}};timer.Start();MergeKey(dialog,Keys.Control|Keys.D5);}Assert(answered&&MergeSequence(dialog.Plan)=="A1,A2,B1,B2,A3,A4,B3,B4","Ctrl+5 accepts a block size through the actual native prompt");MergeKey(dialog,Keys.Control|Keys.D1);
                var menu=(ContextMenuStrip)MergeValue(dialog,"arrangeMenu");var button=FindControls(dialog).OfType<Button>().Single(c=>c.Name=="arrangePages");for(int i=0;i<5;i++)Assert(((ToolStripMenuItem)menu.Items[i]).ShortcutKeyDisplayString=="Ctrl+"+(i+1),"arrange menu displays Ctrl+"+(i+1));bool opened=false;menu.Opened+=delegate{opened=menu.Visible;};button.PerformClick();Assert(opened,"Arrange button opens a reusable native menu");CaptureDialog(dialog,Path.Combine(directory,"combine-arrange-menu.png"));menu.Close();((ToolStripMenuItem)menu.Items[1]).PerformClick();Assert(MergeSequence(dialog.Plan)=="A1,B1,A2,B2,A3,B3,A4,B4","menu click and shortcut use the same A-first arrangement");button.PerformClick();menu.Close();Assert(!menu.IsDisposed,"Arrange menu can reopen after use");dialog.ClientSize=new Size(700,460);Application.DoEvents();Assert(button.Bottom<=button.Parent.ClientSize.Height&&board.Top>=button.Parent.Bottom,"toolbar wraps without hiding the Arrange control or covering the document board");dialog.DialogResult=DialogResult.OK;dialog.Close();}
            UiText.English=false;using(var dialog=new MergeWindow(null)){dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""),"奇数页.pdf");dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-even.pdf"),""),"偶数页.pdf");foreach(var g in dialog.Plan.Groups)g.Expanded=true;dialog.Show();Application.DoEvents();var board=dialog.Controls.OfType<MergeWindow.MergeBoard>().Single();board.Rebuild();MergeDrag(board,MergePoint(board,MergeRect(board,dialog.Plan.Groups[0],0)),MergePoint(board,MergeRect(board,dialog.Plan.Groups[1],0),.15),false);Assert(board.AccessibleDescription.Contains("插入到")&&board.AccessibleDescription.Contains("原第 1 页"),"Chinese merge labels and destination hints remain available");CaptureDialog(dialog,Path.Combine(directory,"combine-detail-zh.png"));MergeKey(board,Keys.Escape);dialog.Scale(new SizeF(1.5f,1.5f));Application.DoEvents();board.Rebuild();Assert(MergeCards(board).Count==8,"150 percent UI scaling keeps the expanded board free of duplicate covers");CaptureDialog(dialog,Path.Combine(directory,"combine-detail-scaled.png"));dialog.DialogResult=DialogResult.OK;dialog.Close();}UiText.English=true;
        }
        static System.Windows.Forms.Timer MergeSavePicker(string path,Action<bool> done){var timer=new System.Windows.Forms.Timer{Interval=70};var start=DateTime.UtcNow;timer.Tick+=delegate{IntPtr dialog=FindWindowEx(IntPtr.Zero,IntPtr.Zero,"#32770",UiText.Get("保存合并的 PDF"));if(dialog==IntPtr.Zero)return;IntPtr edit=IntPtr.Zero;EnumChildWindows(dialog,delegate(IntPtr child,IntPtr parameter){var kind=new StringBuilder(80);var name=new StringBuilder(500);GetClassName(child,kind,kind.Capacity);GetWindowText(child,name,name.Capacity);if(kind.ToString()=="Edit"&&(name.ToString().EndsWith(".pdf",StringComparison.OrdinalIgnoreCase)||name.ToString()=="Combined"))edit=child;return true;},IntPtr.Zero);if(path==null){timer.Stop();done(true);N.SendMessage(GetDlgItem(dialog,2),0xf5,IntPtr.Zero,IntPtr.Zero);}else if(edit!=IntPtr.Zero){timer.Stop();done(true);MergeText(edit,0xc,IntPtr.Zero,path);N.SendMessage(GetDlgItem(dialog,1),0xf5,IntPtr.Zero,IntPtr.Zero);}else if((DateTime.UtcNow-start).TotalSeconds>5){timer.Stop();done(false);N.SendMessage(GetDlgItem(dialog,2),0xf5,IntPtr.Zero,IntPtr.Zero);}};timer.Start();return timer;}
        static void MergeCloseDetails(string directory){UiText.English=true;string prompt=UiText.Get("未保存的修改");using(var dialog=new MergeWindow(null)){dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""),"A-odd.pdf");dialog.Show();Application.DoEvents();string before=dialog.Plan.LayoutKey;using(var answer=AnswerSavePrompt(2,prompt)){N.SendMessage(dialog.Handle,0x112,new IntPtr(0xf060),IntPtr.Zero);Application.DoEvents();Assert(!answer.Enabled&&dialog.Visible&&dialog.DialogResult==DialogResult.None&&dialog.Plan.LayoutKey==before,"caption close prompts and Cancel preserves the entire merge session");}
                bool picker=false;using(var answer=AnswerSavePrompt(6,prompt))using(var file=MergeSavePicker(null,ok=>picker=ok)){dialog.Close();Application.DoEvents();}Assert(picker&&dialog.Visible&&dialog.Plan.LayoutKey==before,"canceling Save As keeps the merge workspace and its page order");using(var answer=AnswerSavePrompt(7,prompt)){dialog.Close();Application.DoEvents();Assert(!answer.Enabled&&!dialog.Visible,"No explicitly discards and closes the merge workspace");}}
            using(var initial=PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""))using(var dialog=new MergeWindow(initial)){dialog.Show();Application.DoEvents();dialog.Plan.Groups[0].Expanded=true;using(var answer=AnswerSavePrompt(2,prompt)){dialog.Close();Application.DoEvents();Assert(answer.Enabled&&!dialog.Visible,"unchanged input and view-only expansion close without a save prompt");}}
            using(var dialog=new MergeWindow(null)){dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""),"A-odd.pdf");dialog.Show();Application.DoEvents();dialog.Plan.Undo();using(var answer=AnswerSavePrompt(2,prompt)){dialog.Close();Application.DoEvents();Assert(answer.Enabled&&!dialog.Visible,"undoing back to an empty unchanged workspace removes the save prompt");}}
            using(var dialog=new MergeWindow(null)){dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""),"A-odd.pdf");bool kept=false;int stage=0;using(var answer=AnswerSavePrompt(2,prompt))using(var action=new System.Windows.Forms.Timer{Interval=100}){action.Tick+=delegate{if(stage++==0){((Button)dialog.CancelButton).PerformClick();return;}kept=dialog.Visible&&dialog.DialogResult==DialogResult.None;action.Stop();dialog.DialogResult=DialogResult.OK;};action.Start();dialog.ShowDialog();}Assert(kept,"the actual Cancel button also prompts and allows editing to continue");}
            string output=Path.Combine(directory,"merge-close-saved.pdf");if(File.Exists(output))File.Delete(output);using(var dialog=new MergeWindow(null)){dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""),"A-odd.pdf");dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-even.pdf"),""),"B-even.pdf");dialog.Plan.Arrange(1);dialog.Show();Application.DoEvents();bool picker=false;using(var answer=AnswerSavePrompt(6,prompt))using(var file=MergeSavePicker(output,ok=>picker=ok)){dialog.Close();Application.DoEvents();}Assert(picker&&!dialog.Visible&&File.Exists(output),"Yes opens native Save As, writes a PDF and closes only after saving");using(var saved=PdfDocument.Open(output,""))Assert(saved.Count==8&&saved.AllText().IndexOf("FEATURE PAGE 2",StringComparison.Ordinal)<saved.AllText().IndexOf("FEATURE PAGE 3",StringComparison.Ordinal),"save-on-close writes the current interleaved order, not the input order");}
            string failed=Path.Combine(directory,"merge-close-failed.pdf");if(File.Exists(failed))File.Delete(failed);using(var dialog=new MergeWindow(null)){dialog.Plan.Add(PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""),"A-odd.pdf");dialog.Plan.Groups[0].Pages[0].Index=int.MaxValue;dialog.Show();Application.DoEvents();bool picker=false;using(var answer=AnswerSavePrompt(6,prompt))using(var file=MergeSavePicker(failed,ok=>picker=ok))using(var error=AnswerSavePrompt(1,UiText.Get("保存失败"))){dialog.Close();Application.DoEvents();Assert(!error.Enabled&&picker&&dialog.Visible&&dialog.Plan.Count==4&&!File.Exists(failed),"simulated page-import failure reports an error and keeps the unsaved workspace");}dialog.DialogResult=DialogResult.OK;dialog.Close();}
            using(var initial=PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""))using(var dialog=new MergeWindow(initial,true)){dialog.Plan.MovePage(dialog.Plan.Groups[0].Pages[0],dialog.Plan.Groups[0],2);using(var answer=AnswerSavePrompt(6,prompt))using(var action=new System.Windows.Forms.Timer{Interval=100}){action.Tick+=delegate{action.Stop();dialog.Close();};action.Start();Assert(dialog.ShowDialog()==DialogResult.OK&&dialog.Plan.Count==4,"organizer close offers Apply and returns the normal apply result");}initial.Organize(dialog.Plan.AllPages(),dialog.BaseSource);initial.OpenPage(0);Assert(initial.Dirty&&initial.SelectedText(0,200).Contains("FEATURE PAGE 3"),"applying through close retains the organizer's requested page order");initial.Undo();Assert(initial.SelectedText(0,200).Contains("FEATURE PAGE 1"),"close-applied page organization remains undoable in the original document");}
            using(var main=new MainWindow(null)){string path=Path.Combine(directory,"scan-odd.pdf");main.LoadForTest(PdfDocument.Open(path,""));main.Show();Application.DoEvents();Assert(main.CanSaveToPath(path)&&!main.CanSaveToPath(path,true),"merge Save As guards all open reader tabs while ordinary Save can update the active document");Assert(main.CanSaveToPath(Path.Combine(directory,"unused-merged.pdf"),true),"merge Save As permits a separate new output file");main.Close();}
            using(var initial=PdfDocument.Open(Path.Combine(directory,"scan-odd.pdf"),""))using(var dialog=new MergeWindow(initial,true)){dialog.Plan.Change(delegate{dialog.Plan.Groups[0].Pages.Clear();});dialog.Show();Application.DoEvents();using(var answer=AnswerSavePrompt(7,prompt)){dialog.Close();Application.DoEvents();Assert(dialog.Visible&&dialog.Plan.Count==0,"empty changed organizer asks before discarding all page adjustments");}using(var answer=AnswerSavePrompt(6,prompt)){dialog.Close();Application.DoEvents();Assert(!dialog.Visible,"empty changed organizer closes after explicit discard confirmation");}}

        }
        static void MergeDetails(string directory){MergeInputs(directory);MergeOrdering(directory);MergeBoardDetails(directory);MergeShortcuts(directory);MergeCloseDetails(directory);}
        internal static int RunMergeDetails(string directory){logPath=Path.Combine(directory,"merge-detail-test.txt");try{MergeDetails(directory);log.AppendLine("TOTAL: "+assertions+" assertions, 0 failures");File.WriteAllText(logPath,log.ToString());return 0;}catch(Exception e){log.AppendLine(e.ToString());File.WriteAllText(logPath,log.ToString());return 1;}}
    }
